// Layer 1: regex for structured identifiers.
// Fast and deterministic, but blind to names in free text.
const patterns = {
  SSN: /\b\d{3}-\d{2}-\d{4}\b/g,
  PHONE_EG: /\b(?:\+?20[ -]?|0)1[0125]\d{8}\b/g,
  PHONE_INTL: /\b(?:\+?\d{1,3}[ -]?)?\(?\d{3}\)?[ -]?\d{3}[ -]?\d{4}\b/g,
  NATIONAL_ID_EG: /\b[23]\d{13}\b/g,
  EMAIL: /\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g,
  MRN: /\bMRN[:# ]?\s?\d{6,10}\b/gi,
  DATE: /\b\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4}\b/g,
  IP: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g,
  URL: /\bhttps?:\/\/[^\s]+/g,
  ACCOUNT: /\bACCT[:# ]?\s?\d{6,12}\b/gi
};

const out = [];
for (const item of $input.all()) {
  const text = item.json.chatInput
    || item.json.text
    || item.json.body?.text
    || '';

  const spans = [];
  for (const [type, re] of Object.entries(patterns)) {
    for (const m of text.matchAll(re)) {
      spans.push({
        type,
        start: m.index,
        end: m.index + m[0].length,
        value: m[0],
        source: 'regex'
      });
    }
  }

  out.push({ json: {
    request_id: item.json.request_id || $execution.id,
    phi_source: item.json.phi_source || 'chat',
    session_id: item.json.sessionId || null,
    text,
    spans
  }});
}
return out;

// De-identification node.
// Inputs: spans from the regex node + entities from the Presidio node.
// Token format: [TYPE_<timeCode>_<rand>]
const REGEX_NODE = 'Regex detect';
const PRESIDIO_NODE = 'Presidio analyze';

// --- Input 1: regex node (carries the original text and its spans) ---
const base = $(REGEX_NODE).first().json;
const text = base.text || '';
const regexSpans = (base.spans || []).map(s => ({ ...s, source: 'regex', score: s.score ?? 1 }));

// --- Input 2: Presidio node ---
// The HTTP Request node may hand back one item holding an array,
// or one item per entity. Handle both, and fall back to $input.
let presidioItems;
try {
  presidioItems = $(PRESIDIO_NODE).all().map(i => i.json);
} catch (e) {
  presidioItems = $input.all().map(i => i.json);
}

// Fail closed: if the NER layer errored, do not continue with regex-only scrubbing.
if (presidioItems.some(x => x && typeof x === 'object' && !Array.isArray(x) && x.error)) {
  throw new Error('PHI gate failed closed: Presidio returned an error');
}
// Entity types that are clinically needed downstream (e.g. "3 hours ago" for dose timing).
const KEEP_CLEAR = new Set(['DATE_TIME', 'NRP']);
let rawEntities = [];
if (presidioItems.length === 1 && Array.isArray(presidioItems[0])) {
  rawEntities = presidioItems[0];
} else if (presidioItems.length === 1 && Array.isArray(presidioItems[0]?.results)) {
  rawEntities = presidioItems[0].results;
} else {
  rawEntities = presidioItems.filter(x => x && x.entity_type);
}

const nerSpans = rawEntities
  .filter(r => typeof r.start === 'number' && typeof r.end === 'number' && !KEEP_CLEAR.has(r.entity_type))
  .map(r => ({
    type: r.entity_type,
    start: r.start,
    end: r.end,
    value: text.slice(r.start, r.end),
    source: 'presidio',
    score: r.score
  }));

// --- Merge both layers, drop overlaps ---
const all = [...regexSpans, ...nerSpans].sort(
  (a, b) => a.start - b.start
    || (b.end - b.start) - (a.end - a.start)
    || (b.score || 1) - (a.score || 1)
);

const merged = [];
for (const s of all) {
  if (!merged.length || s.start >= merged[merged.length - 1].end) merged.push(s);
}

// --- Time-coded random tokens ---
const issuedAt = Date.now();
const timeCode = issuedAt.toString(36).toUpperCase();
let counter = 0;
const randomSuffix = () => {
  counter++;
  const a = Math.floor(Math.random() * 0x100000000).toString(16).padStart(8, '0');
  const b = (issuedAt ^ (counter * 0x9e3779b1)).toString(16).slice(-4);
  return (a + b).toUpperCase().slice(0, 6);
};

// One token per distinct value, so repeated mentions stay linked.
const byValue = new Map();
const mapping = {};
const identifiers = [];

for (const s of merged) {
  const dedupeKey = s.type + '|' + s.value.trim().toLowerCase().replace(/\s+/g, ' ');
  if (!byValue.has(dedupeKey)) {
    const token = `[${s.type}_${timeCode}_${randomSuffix()}]`;
    byValue.set(dedupeKey, token);
    mapping[token] = s.value;
    identifiers.push({
      token,
      entity_type: s.type,
      detected_by: s.source,
      score: s.score,
      issued_at: new Date(issuedAt).toISOString(),
      occurrences: 1
    });
  } else {
    identifiers.find(x => x.token === byValue.get(dedupeKey)).occurrences++;
  }
  s.token = byValue.get(dedupeKey);
}

// Replace right-to-left so earlier offsets stay valid.
let deidentified = text;
for (let i = merged.length - 1; i >= 0; i--) {
  const s = merged[i];
  deidentified = deidentified.slice(0, s.start) + s.token + deidentified.slice(s.end);
}

const counts = merged.reduce((acc, s) => { acc[s.type] = (acc[s.type] || 0) + 1; return acc; }, {});

return [{ json: {
  request_id: base.request_id || $execution.id,
  phi_source: base.phi_source || 'chat',
  mode: 'tokenize',
  reversible: true,
  issued_at: new Date(issuedAt).toISOString(),
  time_code: timeCode,
  expires_at: new Date(issuedAt + 300000).toISOString(),
  deidentified_text: deidentified,
  identifiers,
  mapping,
  entity_counts: counts,
  detected_by_regex: regexSpans.length,
  detected_by_presidio: nerSpans.length,
  dropped_as_overlap: (regexSpans.length + nerSpans.length) - merged.length,
  total_entities: merged.length,
  distinct_entities: Object.keys(mapping).length,
  recognizers: [...new Set(merged.map(s => s.source))]
}}];

// Re-identification: map tokens in the LLM output back to real values.
// Reads the mapping from the de-identification node, not from the LLM.
const DEID_NODE = 'De-identify';
const LLM_NODE = 'AI Agent';

const state = $(DEID_NODE).first().json;
const mapping = state.mapping || {};

// --- Pull the model's text out of whatever shape it arrived in ---
const llm = $input.first().json;
let answer =
  llm.content?.[0]?.text            // Anthropic style
  ?? llm.choices?.[0]?.message?.content  // OpenAI style
  ?? llm.output
  ?? llm.text
  ?? llm.message?.content
  ?? (typeof llm === 'string' ? llm : '');

if (typeof answer !== 'string') answer = JSON.stringify(answer);

// --- TTL check: refuse to re-identify an expired mapping ---
const expired = state.expires_at && Date.now() > new Date(state.expires_at).getTime();

// --- Replace tokens, longest first so no token is a prefix of another ---
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const tokens = Object.keys(mapping).sort((a, b) => b.length - a.length);

let restored = answer;
const restoredCounts = {};

for (const token of tokens) {
  // Case-insensitive: models re-emit tokens in altered casing.
  const re = new RegExp(escapeRe(token), 'gi');
  const hits = (restored.match(re) || []).length;
  if (hits > 0) {
    restoredCounts[token] = hits;
    restored = restored.replace(re, mapping[token]);
  }
}

// --- Validate: any surviving token means re-identification failed ---
const residual = restored.match(/\[[A-Z_]+_[A-Z0-9]+_[A-Z0-9]+\]/g) || [];

// --- Leak check: did the model echo a raw value we never gave it? ---
// (Only meaningful if the model was supposed to see tokens only.)
const leaked = Object.values(mapping).filter(v =>
  v.length > 4 && answer.toLowerCase().includes(v.toLowerCase())
);

const ok = !expired && residual.length === 0 && leaked.length === 0;
const src = state.phi_source || 'chat';
const upstream = $input.first().json;
const FALLBACK = 'تعذّر تسليم الإجابة بشكل آمن (فشل التحقق من الخصوصية). تم تسجيل الحالة وإبلاغ المراجع البشري.';
let finalAnswer = restored;
if (ok && src !== 'telegram') {
  finalAnswer += '\n\n---\n⚠️ معلومات مساندة لقرار الطبيب المختص وليست بديلاً عن التقييم الإكلينيكي. في الطوارئ اتصل بالإسعاف 123 أو مركز السموم/أقرب طوارئ.';
}
if (ok && upstream.readability && upstream.readability.flesch_kincaid_grade > upstream.readability.target_grade) {
  finalAnswer += '\n\n⚠️ لم يصل النص لمستوى القراءة المستهدف بعد المحاولات المسموحة — يلزم مراجعة الطبيب قبل إرساله للمريض.';
}
const needsReview = /urgent\s*-\s*escalate|intentional|self[- ]?harm|suicid|deliberate overdose/i.test(answer);

return [{ json: {
  request_id: state.request_id,
  phi_source: state.phi_source || 'chat',
  reidentified: ok,
  answer: ok ? finalAnswer : FALLBACK,
  needs_human_review: needsReview,
  translation_report: upstream.translation_report || null,
  router: upstream.router || null,
  tokens_in_mapping: tokens.length,
  tokens_restored: Object.keys(restoredCounts).length,
  restored_counts: restoredCounts,
  residual_tokens: residual.length,
  residual_list: residual,
  raw_phi_echoed: leaked.length,
  expired,
  issued_at: state.issued_at,
  expires_at: state.expires_at,
  entity_counts: state.entity_counts,
  recognizers: state.recognizers,
  failure_reason: ok ? null
    : expired ? 'mapping_expired'
    : residual.length ? 'unmapped_tokens_remain'
    : 'raw_phi_in_model_output'
}}];

// Unified audit log. Never stores PHI: only ids, counts, flags and reasons.
const item = $input.first().json;
const reasons = [];
if (item.injection_detected) reasons.push('prompt_injection');
if (item.escalation_detected) reasons.push('harm_escalation');
if (item.reidentified === false) reasons.push(item.failure_reason || 'reidentify_failed');
if (item.needs_human_review) reasons.push('clinical_review_flag');
if (item.translation_report && item.translation_report.valid === false) reasons.push('translation_validation_failed');

const audit_entry = {
  event: (item.injection_detected || item.escalation_detected) ? 'guard_block' : 'phi_scrub_audit',
  timestamp: new Date().toISOString(),
  request_id: item.request_id || $execution.id,
  source: item.phi_source || 'chat',
  reidentified: item.reidentified ?? null,
  entity_counts: item.entity_counts || null,
  recognizers: item.recognizers || null,
  tokens_in_mapping: item.tokens_in_mapping ?? null,
  tokens_restored: item.tokens_restored ?? null,
  failure_reason: item.failure_reason || null,
  injection_detected: !!item.injection_detected,
  escalation_detected: !!item.escalation_detected,
  translation_valid: item.translation_report ? item.translation_report.valid : null,
  router_tier: item.router ? item.router.risk_tier : null,
  router_status: item.router ? item.router.status : null,
  reasons,
  escalate: reasons.length > 0
};
console.log(JSON.stringify(audit_entry));

// Persist the last 500 entries (active/production executions only).
const sd = $getWorkflowStaticData('global');
sd.audit = sd.audit || [];
sd.audit.push(audit_entry);
if (sd.audit.length > 500) sd.audit.shift();

return [{ json: { ...item, audit_log: audit_entry } }];

