// Layer 2 guard: prompt-injection + harm/self-harm escalation (input side).
// Runs on the de-identified text (chat path) or on the raw transcript (Telegram path).
const AR = '؀-ۿ';
const injectionPatterns = [
  /ignore (all|any|the)? ?(previous|prior|above) (instructions|rules)/i,
  /disregard (all|any|the)? ?(previous|prior) (instructions|rules)/i,
  /forget (everything|all|your) (instructions|rules)/i,
  /you are now (a|an|the|in|my|dan)\b/i,
  /\bact as (if )?(you are|you were|an? (unrestricted|uncensored|jailbroken|different|new)\b)/i,
  /without (any )?(restrictions|limits|guardrails|filters)/i,
  /from now on,? you (will|must|are|can)\b/i,
  /(hidden|secret|internal) (rules|instructions|prompt)/i,
  /pretend (you|to) (are|be)/i,
  /(show|print|reveal|repeat) (me )?(your|the) (system )?(instructions|prompt|system message)/i,
  /system prompt/i,
  /jailbreak/i,
  /developer mode/i,
  /bypass (the )?(safety|guardrails?|filters?|rules)/i,
  /تجاهل\s*(كل\s*)?(التعليمات|القواعد|الأوامر|ما سبق)/,
  /انسى\s*(كل\s*)?(التعليمات|القواعد)/,
  /تصرف\s*(وكأنك|كأنك)/,
  /(اكشف|اعرض)( لي)?\s*(التعليمات|البرومبت)/,
];
// Intent-based only: a clinician describing a past overdose or "suicide attempt" is NOT blocked.
const escalationPatterns = [
  /\b(kill|hurt|harm) (myself|him|her|them)\b/i,
  /\bwant(s)? to (die|end my life|kill myself)\b/i,
  /\b(going|plan(ning)?|want) to (commit )?suicide\b/i,
  /\bend my life\b/i,
  /\bi(?:'m| am)? (?:thinking|having thoughts?) (?:about|of) (?:suicide|killing myself|ending (?:it|my life))/i,
  /\b(?:don'?t|do not) want to (?:live|be alive|go on)(?:\s*any ?more|[.!?]?\s*$)/i,
