// Deterministic validation of the Arabic translation (no LLM involved).
const en = String($('Flesch-Kincaid').last().json.output || '');
const ar = String($('Translate EN to AR').first().json.output || '');
const bt = String($input.first().json.output || '');
const state = $('De-identify').first().json;
const readability = $('Flesch-Kincaid').last().json.readability;

const toAscii = s => s
  .replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 0x0660))
  .replace(/[۰-۹]/g, d => String(d.charCodeAt(0) - 0x06F0))
  .replace(/٫/g, '.').replace(/٬/g, '');
const tokRe = /\[[A-Z_]+_[A-Z0-9]+_[A-Z0-9]+\]/gi;
const W = {two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,twelve:12};
const wordsToDigits = s => s.replace(/\b(two|three|four|five|six|seven|eight|nine|ten|twelve)\b/gi, m => W[m.toLowerCase()])
  .replace(/(ساعتين|يومين|دقيقتين|أسبوعين|اسبوعين|شهرين)/g, m => '2 ' + m);
const clean = s => wordsToDigits(toAscii(s)).replace(tokRe, ' ').replace(/^\s*\d+[.)]\s+/gm, '');   // drop tokens + list numbering
const nums = s => (clean(s).match(/\d+(?:\.\d+)?/g) || []).sort();
const toks = s => ((s.match(tokRe) || []).map(t => t.toUpperCase())).sort();
const same = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);

const nEn = nums(en), nAr = nums(ar), nBt = nums(bt);
const checks = {
  arabic_present: /[؀-ۿ]/.test(ar) && ar.trim().length > 0,
  numbers_match_arabic: same(nEn, nAr),
  numbers_match_backtranslation: same(nEn, nBt),
  tokens_preserved: same(toks(en), toks(ar)),
};
const words = s => new Set((s.toLowerCase().match(/[a-z]{3,}/g) || []));
const A = words(en), B = words(bt);
const inter = [...A].filter(w => B.has(w)).length;
const similarity = A.size ? Number((inter / (A.size + B.size - inter)).toFixed(2)) : 0;

const valid = Object.values(checks).every(Boolean);
const output = valid
  ? ar + '\n\n---\nEnglish version:\n' + en
  : en + '\n\n⚠️ الترجمة العربية لم تجتز التحقق الآلي (الأرقام/الجرعات)، لذلك نعرض النص الإنجليزي فقط. يلزم مراجعة مترجم أو طبيب.';

return [{ json: {
  output,
  request_id: state.request_id,
  phi_source: state.phi_source,
  readability,
  translation_report: { valid, checks, numbers_source: nEn, numbers_arabic: nAr, numbers_backtranslation: nBt, backtranslation_similarity: similarity }
}}];

// The Risk Router answered directly (LOW = local model, CRITICAL = pending human approval).
// MEDIUM/HIGH never get here: they continue to the full Case Analyzer + Advisor pipeline.
const r = $input.first().json;
let answer;
if (r.status === 'pending_human_approval') {
  answer = 'هذه الحالة مصنّفة **حرجة** (Critical). لا يتم إصدار إجابة آلية قبل مراجعة وموافقة طبيب مختص — تم إرسال طلب الموافقة للمراجع (رقم الطلب: ' + r.request_id + ').\n\nفي حالة الطوارئ اتصل فورًا بالإسعاف 123 أو مركز السموم 08008880700.\n\nURGENT - escalate to emergency care / poison center now.';
} else {
  answer = String(r.answer || '');
}
return [{ json: { output: answer, router: { request_id: r.request_id, status: r.status, risk_tier: r.risk_tier, model_path: r.model_path || null } } }];

// FAIL CLOSED: the risk router did not return a usable tier, so no answer is generated.
const req = $('De-identify').first().json;
const msg = 'تعذّر تصنيف مستوى الخطورة لهذا الطلب حاليًا، لذلك لم يتم إنشاء إجابة آلية. من فضلك اعرض الحالة على طبيب مختص أو مركز السموم. في الطوارئ اتصل بالإسعاف 123 أو مركز السموم 08008880700.';
return [{ json: { output: msg, router: { request_id: req.request_id, status: 'router_unavailable', risk_tier: null, model_path: null } } }];

// Asks the Monitoring workflow whether the hard stop is active. If the monitor is unreachable the chat continues (availability); the Router call below still fails closed.
const items = $input.all();
let paused = false, reason = null;
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/webhook/monitor-status', json: true, timeout: 5000 });
  paused = !!(r && r.paused === true); reason = (r && r.reason) || null;
} catch (e) { paused = false; }
return items.map(i => ({ json: { ...i.json, pause_state: { paused, reason } } }));
